@import "tailwindcss";

:root {
  --studio-bg: #040a0a;
  --studio-surface: #0a1917;
  --studio-accent: #d4b46a;
  --studio-text: #f5f2eb;
  --studio-muted: #a4b7b2;
}

@keyframes shimmerSlide {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@keyframes aetherBorderSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes aetherPrismSweep {
  0%, 100% { opacity: 0.4; transform: translateX(-12%) skewX(-16deg); }
  50% { opacity: 0.9; transform: translateX(12%) skewX(-16deg); }
}
@keyframes aetherEtchBreathe {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 0.9; }
}
@keyframes aetherActiveHalo {
  0%, 100% { box-shadow: 0 0 16px #d4b46a33, inset 0 1px 0 rgba(255,255,255,0.16); }
  50% { box-shadow: 0 0 32px #d4b46a66, inset 0 1px 0 rgba(255,255,255,0.28); }
}

.aether-fresnel-top {
  box-shadow: inset 0 1px 0 0 rgba(255, 255, 255, 0.2), inset 0 -1px 0 0 rgba(0, 0, 0, 0.45);
}
.aether-cta-primary {
  background: linear-gradient(135deg, #d4b46a, #f4e6cf);
  color: #040a0a;
  border-radius: 14px;
  box-shadow: 0 6px 0 #040a0a, 0 14px 30px -6px #d4b46a66, inset 0 1px 0 rgba(255,255,255,0.45);
}

